async def _drain(futures: list["asyncio.Future[None]"]) -> None:
    """Wait for every future to finish, re-issuing cancellation and retrying if
    the wait itself is cancelled, so cleanup always completes."""
    remaining = list(futures)
    while remaining:
        try:
            await asyncio.gather(*remaining, return_exceptions=True)
            return
        except asyncio.CancelledError:
            for fut in remaining:
                if not fut.done():
                    fut.cancel()
        remaining = [f for f in remaining if not f.done()]

